<script setup lang="ts">
import { computed, onMounted, ref } from 'vue';
import { api, ClientError, OfflineError } from '../api';
import { COPY } from '../copy';
import type { Curriculum } from '../types';
import ProgressPanel from '../components/ProgressPanel.vue';
interface Aggregate {studyDays:number;durationMs:number;minutes:number;new:number;masteredNew:number;accuracy:number|null}
interface Summary {daily:{day:string;new:number;review:number;practice:number;answers:number;correct:number;accuracy:number|null;durationMs:number;completed:boolean;makeup:boolean}[];totals:Aggregate&{thisWeek:Aggregate;last7:Aggregate};streak:{current:number;best:number;makeupUsed:number};wrongTop20:{headword:string;wrong_count:number;last_wrong_at:string;topQtype:string|null;inBook:boolean}[];progress:Curriculum;generatedAt:string}
const summary=ref<Summary|null>(null),error=ref(''),busy=ref(false);
async function load(){if(busy.value)return;busy.value=true;error.value='';try{summary.value=await api('/api/parent/summary?days=30');}catch(e){if(e instanceof OfflineError)error.value='连不上学习服务。如果不在家，请先打开 Tailscale；在家的话请家长看一下 Studio 是否开机。';else if(e instanceof ClientError)error.value=e.message;else throw e;}finally{busy.value=false;}}
onMounted(load);
const max=computed(()=>Math.max(1,...(summary.value?.daily.map(d=>d.new+d.review+d.practice)??[])));
const chartSegments=computed(()=>{
  const segments:{x:number;y:number;day:string;accuracy:number}[][]=[];let current:{x:number;y:number;day:string;accuracy:number}[]=[];
  summary.value?.daily.forEach((d,i)=>{if(d.accuracy===null){if(current.length)segments.push(current);current=[];}else current.push({x:i*1000/29,y:56-d.accuracy*48,day:d.day,accuracy:Math.round(d.accuracy*100)});});
  if(current.length)segments.push(current);return segments;
});
const timestamp=computed(()=>summary.value?new Date(summary.value.generatedAt).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',month:'long',day:'numeric',hour:'2-digit',minute:'2-digit'}):'');
const percent=(n:number|null)=>Math.round((n??0)*100);
</script>
<template><header class="ptop"><div class="in"><div class="brand"><span class="logo">W</span>{{ COPY.dashboard }}</div><span class="chip">{{ COPY.parentReadonly }}</span><span v-if="summary" class="parent-date">{{ COPY.dataAsOf(timestamp) }}</span></div></header><main class="page"><p v-if="error" class="offline" role="status">{{ error }} <button :disabled="busy" @click="load">{{ COPY.retry }}</button></p><template v-if="summary"><p>{{ COPY.weekReport(summary.totals.thisWeek.studyDays,Math.round(summary.totals.thisWeek.minutes),summary.totals.thisWeek.masteredNew,summary.wrongTop20.slice(0,2).map(w=>w.headword).join('、')||COPY.noRecords) }}</p><div class="kpis"><div class="kpi"><b>{{ summary.totals.studyDays }}<small> / 30 天</small></b><span>{{ COPY.learningDays }}</span></div><div class="kpi"><b>{{ summary.streak.current }} 天</b><span>连续打卡（含补签 {{ summary.streak.makeupUsed }} 次）</span></div><div class="kpi"><b>{{ Math.floor(Math.round(summary.totals.durationMs/60000)/60) }} 小时 {{ Math.round(summary.totals.durationMs/60000)%60 }} 分</b><span>{{ COPY.learningDuration }} · 日均 {{ summary.totals.studyDays?Math.round(summary.totals.minutes/summary.totals.studyDays):0 }} 分</span></div><div class="kpi"><b>{{ summary.totals.accuracy===null?COPY.noRecords:percent(summary.totals.accuracy)+'%' }}</b><span>{{ COPY.learningAccuracy }}</span></div></div>
<section class="panel"><div class="cal-head"><h2>{{ COPY.dailyVolume }}</h2><span class="small muted">新词 / 复习 / 练习</span></div><div class="chart" role="img" aria-label="近 30 天每天新词、复习和练习数量"><div v-for="d in summary.daily" :key="d.day" class="col" :class="{zero:!d.answers}" :title="`${d.day}：新词 ${d.new}，复习 ${d.review}，练习 ${d.practice}，正确率 ${d.accuracy===null?COPY.noRecords:percent(d.accuracy)+'%'}`"><i class="n" :style="{height:`${d.new/max*100}%`}"></i><i class="r" :style="{height:`${d.review/max*100}%`}"></i><i class="p" :style="{height:`${d.practice/max*100}%`,background:'var(--amber)'}"></i></div></div><div class="xaxis"><span v-for="i in [0,7,14,21,29]" :key="i">{{ summary.daily[i]?.day.slice(5).replace('-','月') }}日</span></div><h2 style="margin-top:20px">{{ COPY.dailyAccuracy }}</h2><svg class="accuracy-chart" viewBox="0 0 1000 64" preserveAspectRatio="none" role="img" aria-label="每日正确率，无作答日不连线"><g v-for="(segment,i) in chartSegments" :key="i"><polyline v-if="segment.length>1" :points="segment.map(p=>`${p.x},${p.y}`).join(' ')" fill="none" stroke="var(--ok)" stroke-width="2" vector-effect="non-scaling-stroke"/><circle v-for="p in segment" :key="p.day" :cx="p.x" :cy="p.y" r="2" fill="var(--ok)"><title>{{ p.day }}：{{ p.accuracy }}%</title></circle></g></svg></section>
<div class="two"><section class="panel parent-table"><h2>{{ COPY.wrongTop }}</h2><table class="top20"><thead><tr><th>#</th><th>单词</th><th>错的次数</th><th>{{ COPY.mainFailure }}</th></tr></thead><tbody><tr v-for="(w,i) in summary.wrongTop20" :key="w.headword"><td class="small muted">{{ i+1 }}</td><td class="w">{{ w.headword }} <span v-if="!w.inBook" class="small muted">{{ COPY.removed }}</span></td><td>{{ w.wrong_count }}</td><td class="small muted">{{ w.topQtype?COPY.qtypes[w.topQtype]:COPY.noRecords }}</td></tr></tbody></table><p v-if="!summary.wrongTop20.length" class="muted">{{ COPY.noRecords }}</p></section><div class="stack"><ProgressPanel :curriculum="summary.progress" /><section class="panel"><h2>{{ COPY.explanation }}</h2><p class="small muted">{{ COPY.parentNote }}</p></section></div></div><p class="foot">{{ COPY.parentFooter }}</p></template></main></template>
